Result MapBook::match(Order& order) {
    Result result{Status::Accepted, RejectReason::None, 0, 0};
    Levels& book = levels(opposite(order.side));
    while (order.quantity > 0 && !book.empty()) {
        auto levelIt = book.begin();
        const Price levelPrice = levelIt->first;
        if (!crosses(order, levelPrice)) {
            break;
        }

        Level& level = levelIt->second;
        while (order.quantity > 0 && !level.orders.empty()) {
            Resting& resting = level.orders.front();
            const Quantity quantity = std::min(order.quantity, resting.quantity);
            // Trade at the resting order's price.
            emit(EventType::Fill, RejectReason::None, order, resting.id, levelPrice, quantity);
            order.quantity -= quantity;
            resting.quantity -= quantity;
            level.quantity -= quantity;
            ++result.fillCount;
            result.filledQuantity += quantity;
            if (resting.quantity == 0) {
                index_.erase(resting.id);
                level.orders.pop_front();
            }
        }
        if (level.orders.empty()) {
            book.erase(levelIt);
        }
    }
    return result;
}

// High bit set in each byte equal to tag. May also flag a byte just above a
// true match (a borrow artifact); callers compare keys, so that is harmless.
static std::uint64_t match_tag(std::uint64_t group, std::uint8_t tag) noexcept {
  std::uint64_t x = group ^ (kLsbs * tag);
  return (x - kLsbs) & ~x & kMsbs;
}
// kEmpty is the only control value with bit 7 set and bit 1 clear.
static std::uint64_t match_empty(std::uint64_t group) noexcept {
  return group & ~(group << 6) & kMsbs;
}
static std::uint64_t match_free(std::uint64_t group) noexcept { return group & kMsbs; }
static std::size_t lowest_byte(std::uint64_t mask) noexcept {
  return static_cast<std::size_t>(std::countr_zero(mask)) / 8;
}

std::size_t find_index(std::uint64_t h, key_type key) const noexcept {
  std::size_t g = (h >> 7) & group_mask_;
  for (std::size_t step = 1;; ++step) {
    std::uint64_t group = load_group(g);
    for (std::uint64_t m = match_tag(group, h2(h)); m != 0; m &= m - 1) {
      std::size_t i = g * kGroupWidth + lowest_byte(m);
      if (keys_[i] == key && is_full(ctrl_[i])) return i;
    }
    if (match_empty(group) != 0) return kNone;
    g = (g + step) & group_mask_;
  }
}

def implied_volatility(
    market_price: float,
    S: float,
    K: float,
    T: float,
    r: float,
    option_type_flag: int,
    q: float = 0.0,
) -> IVResult:
    """Black-Scholes implied volatility with bounds checks, Newton and a Brent fallback.

    Failed solves return sigma NaN with a reason code; an unconverged iterate is never
    returned.
    """
    nan = float("nan")
    if not all(math.isfinite(x) for x in (market_price, S, K, T, r, q)):
        return IVResult(nan, False, 0, "invalid_input")
    if T <= 0 or S <= 0 or K <= 0:
        return IVResult(nan, False, 0, "invalid_input")
    if market_price <= 0:
        return IVResult(nan, False, 0, "zero_price")

    # Static no-arbitrage bounds on a European option price
    fwd_spot = S * math.exp(-q * T)
    disc_strike = K * math.exp(-r * T)
    if option_type_flag == CALL:
        lower, upper = max(0.0, fwd_spot - disc_strike), fwd_spot
    else:
        lower, upper = max(0.0, disc_strike - fwd_spot), disc_strike
    if market_price <= lower:
        return IVResult(nan, False, 0, "at_or_below_intrinsic")
    if market_price >= upper:
        return IVResult(nan, False, 0, "above_upper_bound")

    def objective(sig: float) -> float:
        return black_scholes_price(S, K, T, r, sig, option_type_flag, q) - market_price

    # Brenner-Subrahmanyam initial guess, clamped into the bracket
    sigma = market_price / fwd_spot * math.sqrt(2 * math.pi / T)
    sigma = min(max(sigma, SIGMA_LO), SIGMA_HI)

    for i in range(1, MAX_NEWTON_ITER + 1):
        vega = calculate_vega(S, K, T, r, sigma, q)
        if vega < MIN_VEGA_PER_SPOT * S:
            break
        step = objective(sigma) / vega
        new_sigma = sigma - step
        if not SIGMA_LO <= new_sigma <= SIGMA_HI:
            break
        sigma = new_sigma
        if abs(step) < SIGMA_TOL:
            return IVResult(sigma, True, i, "ok")

    # Newton left the bracket, stalled on a flat vega, or ran out of steps
    if objective(SIGMA_LO) * objective(SIGMA_HI) > 0:
        return IVResult(nan, False, 0, "outside_bracket")
    # brentq raises if it fails to converge
    sigma, info = brentq(objective, SIGMA_LO, SIGMA_HI, xtol=SIGMA_TOL, full_output=True)
    return IVResult(float(sigma), True, info.iterations, "ok")

def taker_fee(count: int, price: float) -> float:
    """Fee in dollars for `count` contracts at `price` dollars."""
    raw_cents = settings.FEE_RATE * count * price * (1.0 - price) * 100
    return math.ceil(round(raw_cents, 6)) / 100.0


def fee_adjusted_price(price: float) -> float:
    """Cost per contract including the unrounded per-contract fee."""
    return price + settings.FEE_RATE * price * (1.0 - price)


class RiskManager:
    @staticmethod
    def calculate_kelly_size(bankroll: float, win_prob: float, market_price: float) -> float:
        """Dollars to hold in a YES contract bought at market_price (dollars)."""
        if not 0.0 < market_price < 1.0 or not 0.0 <= win_prob <= 1.0:
            return 0.0
        # Shrink the model toward the market: the model is an estimate, not truth.
        p = market_price + settings.SHRINKAGE * (win_prob - market_price)
        q = fee_adjusted_price(market_price)
        # Binary contract bought at q pays 1: win 1 - q per dollar risked q.
        # Kelly fraction f = p - (1 - p) * q / (1 - q) = (p - q) / (1 - q).
        if p <= q:
            return 0.0
        raw_kelly = (p - q) / (1.0 - q)
        allocation = bankroll * raw_kelly * settings.KELLY_FRACTION
        return max(0.0, min(allocation, settings.MAX_POSITION_SIZE))

public func nudges(
    for contacts: [Contact], now: Date, calendar: Calendar, snoozes: SnoozeBook = SnoozeBook()
) -> [Nudge] {
    var best: [ContactID: Nudge] = [:]
    for contact in contacts where !contact.paused && !snoozes.isSnoozed(contact.id, at: now) {
        for candidate in Self.candidates(for: contact, now: now, calendar: calendar) {
            if let current = best[contact.id], !Self.ordered(candidate, before: current) {
                continue
            }
            best[contact.id] = candidate
        }
    }
    var result = Array(best.values)
    if let weekday = settings.checkInWeekday, calendar.component(.weekday, from: now) == weekday {
        result.append(Nudge(kind: .checkIn, contact: nil, ring: nil, priority: Priority.checkIn))
    }
    result.sort(by: Self.ordered)
    return Array(result.prefix(settings.dailyCap))
}
